"""Removes the tool-generated footer that some PR tooling appends to pull
request descriptions ("Generated by/with [Claude Code](...)" and session
links), keeping the rest of the description as written.

    python3 .github/scripts/pr_footer.py --pr 11     # one pull request
    python3 .github/scripts/pr_footer.py             # every pull request
    python3 .github/scripts/pr_footer.py --dry-run   # report only

Needs GITHUB_TOKEN (or GH_TOKEN) with pull-requests: write, and
GITHUB_REPOSITORY (owner/name). Run by .github/workflows/pr-footer.yml.
"""
import argparse
import json
import os
import re
import sys
import urllib.request

API = "https://api.github.com"

# A footer line: the attribution itself, a bare session link, or a robot emoji
# line in front of either.
FOOTER_LINE = re.compile(
    r"^\s*(?:🤖\s*)?(?:_?Generated (?:by|with) \[Claude Code\]\([^)]*\)_?\.?"
    r"|https://claude\.ai/code/\S*|Co-Authored-By: Claude[^\n]*)\s*$",
    re.I,
)


def strip_footer(body):
    """Body without a trailing block of footer lines (and the rule or blank
    lines just above it). Returns the body unchanged if it has none."""
    if not body:
        return body
    lines = body.replace("\r\n", "\n").split("\n")
    end = len(lines)
    while end and not lines[end - 1].strip():
        end -= 1
    cut = end
    while cut and (FOOTER_LINE.match(lines[cut - 1]) or not lines[cut - 1].strip()):
        cut -= 1
    if not any(FOOTER_LINE.match(l) for l in lines[cut:end]):
        return body
    while cut and lines[cut - 1].strip() in ("", "---", "***", "___"):
        cut -= 1
    return "\n".join(lines[:cut]).rstrip() + "\n"


def call(method, path, token, data=None):
    req = urllib.request.Request(API + path, method=method,
                                 data=json.dumps(data).encode() if data is not None else None,
                                 headers={"Authorization": f"Bearer {token}",
                                          "Accept": "application/vnd.github+json",
                                          "X-GitHub-Api-Version": "2022-11-28"})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)


def pulls(repo, token):
    page = 1
    while True:
        batch = call("GET", f"/repos/{repo}/pulls?state=all&per_page=100&page={page}", token)
        yield from batch
        if len(batch) < 100:
            return
        page += 1


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--pr", type=int, help="only this pull request")
    ap.add_argument("--dry-run", action="store_true")
    a = ap.parse_args()
    token = os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN")
    repo = os.environ.get("GITHUB_REPOSITORY")
    if not token or not repo:
        sys.exit("needs GITHUB_TOKEN and GITHUB_REPOSITORY")
    prs = [call("GET", f"/repos/{repo}/pulls/{a.pr}", token)] if a.pr else pulls(repo, token)
    changed = 0
    for pr in prs:
        body = pr.get("body") or ""
        new = strip_footer(body)
        if new == body:
            continue
        changed += 1
        print(f"#{pr['number']}: footer removed{' (dry run)' if a.dry_run else ''}")
        if not a.dry_run:
            call("PATCH", f"/repos/{repo}/pulls/{pr['number']}", token, {"body": new})
    print(f"{changed} pull request(s) changed")


if __name__ == "__main__":
    main()
